function updateTabGuide(){
 const model=activeTab==='modelo',viewer=activeTab==='visualizador';
 for(const [id,yes] of [['tabTelas',!model&&!viewer],['tabModelo',model],['tabVisualizador',viewer]]){E(id).classList.toggle('active',yes);E(id).setAttribute('aria-selected',String(yes));}
 E('workspaceEditor').hidden=viewer;E('viewerPane').hidden=!viewer;
 E('tabGuide').hidden=viewer;E('metrics').hidden=viewer;
 E('treeTitle').textContent=model?'☷ Explorador da tela-modelo':'☷ Explorador de telas reais';
 E('guideTitle').textContent=model?'Tela-Modelo · Padronização progressiva':'Telas reais · '+visibleScreens().length+' telas';
 E('guideDesc').textContent=model?'Exemplo modular da Fase 1, com READMEs e prévia HTML.':'Contratos modulares com Identidade, Classificação, Estrutura, Navegação e Componentes. Use Visualizador para ver cada tela em HTML estático.';
 E('guideReadme').textContent=model?'▤ README do modelo':'▤ README da Home';
 E('guideMatrix').hidden=!model;E('guidePreview').hidden=!model;
 E('exportTabZip').textContent=model?'↧ Exportar modelo ZIP':'↧ Exportar telas ZIP';
 E('exportTabJson').textContent=model?'↧ Modelo JSON':'↧ Telas JSON';
}
function visibleScreens(){return findScreens().filter(n=>activeTab==='modelo'?inModel(n):!inModel(n));}
function switchTab(tab){if(tab!==activeTab&&!ensureSaved())return;activeTab=tab;
 if(tab==='visualizador'){render();if(!viewerSelectedId||!visibleScreens().some(s=>s.id===viewerSelectedId))viewerSelectedId=visibleScreens()[0]?.id||null;renderViewerList();renderViewerPreview();return;}
 const target=tab==='modelo'?modelRoot():workspace.root;if(!target){toast('A pasta _modelo não existe.',true);return;}
 if(tab==='modelo'&&!inModel(selected().node))selectedId=(visibleScreens()[0]||target).id;
 if(tab==='telas'&&inModel(selected().node))selectedId=(visibleScreens()[0]||workspace.root).id;
 expandParents(selectedId);render();}
function render(){updateTabGuide();if(activeTab==='visualizador'){renderViewerList();return;}renderMetrics();renderTree();renderEditor();updateButtons();}
function updateButtons(){const n=selected().node;E('addFolder').disabled=!targetFolder();E('addDoc').disabled=!targetFolder();E('rename').disabled=n.id===workspace.root.id;E('delete').disabled=n.id===workspace.root.id;E('downloadSingle').disabled=n.id===workspace.root.id;E('assemble').disabled=count(workspace.root).screens===0;E('viewCurrent').disabled=!ancestorScreen(selectedId);}
function exportActiveTabJson(){if(!ensureSaved())return;const base=workspace.root;if(activeTab==='modelo'){
 const m=modelRoot();if(!m)return toast('Modelo não encontrado',true);
 const clone={...base,children:[m]};blobDownload('AdvogadoJa_Tela_Modelo_Arvore.json',formatJSON({...workspace,root:clone}),'application/json');toast('Tela-Modelo exportada em JSON.');
 }else{
 const clone={...base,children:base.children.filter(x=>x.name!=='_modelo')};blobDownload('AdvogadoJa_110_Telas_Arvore.json',formatJSON({...workspace,root:clone}),'application/json');toast('Telas reais exportadas em JSON.');}}
function zipEntriesAsTree(files){let seq=0;const root={id:'z0',kind:'folder',name:'telas',children:[]};
 const dirs=new Map([['',root]]);function getDir(parts){let k='',at=root;for(const part of parts){k+=(k?'/':'')+part;if(!dirs.has(k)){const x={id:'z'+(++seq),kind:'folder',name:part,children:[]};at.children.push(x);dirs.set(k,x);}at=dirs.get(k);}return at;}
 for(const f of files){let parts=f.name.replace(/\\/g,'/').split('/').filter(Boolean);const i=parts.indexOf('telas');if(i>=0)parts=parts.slice(i+1);
 if(!parts.length)continue;if(parts.some(p=>!nameOk(p)))throw Error('Nome inválido dentro do ZIP: '+f.name);
 if(f.isDir){getDir(parts);continue}const parent=getDir(parts.slice(0,-1));const name=parts.at(-1);
 const file={id:'z'+(++seq),kind:'file',name,encoding:isText(name)?'text':'base64',content:isText(name)?textPayload(f.bytes):toBase64(f.bytes)};
 const old=parent.children.findIndex(c=>c.name===name);if(old>=0)parent.children.splice(old,1);parent.children.push(file);
 }
 function mark(n){if(!isDir(n))return;const ident=folderChild(n,'identidade'),estr=folderChild(n,'estrutura'),cla=folderChild(n,'classificacao');if(fileChild(ident,'identidade.json')&&fileChild(estr,'estrutura.json')&&fileChild(folderChild(n,'componentes'),'instancias.json')&&cla)n.kind='screen';for(const c of n.children)if(isDir(c))mark(c)}mark(root);
 return{format:DATA_FORMAT,schemaVersion:1,title:'AdvogadoJá — árvore importada de ZIP',root};}
async function convertZipJson(file){try{const data=zipEntriesAsTree(await readZIP(await file.arrayBuffer()));const scr=[];(function walk(n){if(n.kind==='screen')scr.push(n);if(isDir(n))n.children.forEach(walk)})(data.root);
 blobDownload('AdvogadoJa_ZIP_Convertido_Arvore.json',formatJSON(data),'application/json');toast('ZIP convertido em JSON: '+scr.length+' telas; a árvore aberta não foi modificada.');}
 catch(err){toast('Erro convertendo ZIP em JSON: '+err.message,true)}}
function addZipEntries(files){const dt=zipEntriesAsTree(files);const from=dt.root;let added=0;
 function join(parent,child){const old=parent.children.find(c=>c.name===child.name);if(!old){parent.children.push(child);added+=count(child).files;return;}
  if(isDir(old)&&isDir(child)){for(const c of child.children)join(old,c);if(child.kind==='screen')old.kind='screen';}
  else if(old.kind==='file'&&child.kind==='file'){old.content=child.content;old.encoding=child.encoding;added++;}
  else throw Error('Conflito entre pasta e arquivo: '+child.name);
 }
 for(const c of from.children)join(workspace.root,c);detectScreens();return added;
}
function normalizeScreen(screen){const d=assembleScreen(screen),refs=d.tela.componentes?.instanciasRefs||{};return{
 identidade:d.tela.identidade||{},classificacao:d.tela.classificacao||{},navegacao:d.tela.navegacao||{},estrutura:d.tela.estrutura||{},instancias:refs,definicoes:d.componentes||{},id:d.tela.identidade.id};}
function getViewerScreen(){return findScreens().find(s=>s.id===viewerSelectedId&&!inModel(s))||null}
function renderViewerList(){const all=findScreens().filter(s=>!inModel(s)),q=(E('viewerSearch').value||'').trim().toLowerCase();
 const shown=all.filter(s=>{let id='',name='';try{const x=loadJson(fileChild(folderChild(s,'identidade'),'identidade.json'),'identidade');id=x?.id||'';name=x?.nomeExibicao||x?.nome||'';}catch(_){}return(id+' '+name).toLowerCase().includes(q)});
 E('viewerCounter').textContent=shown.length+' de '+all.length+' telas';const box=E('viewerList');box.replaceChildren();
 for(const s of shown){const info=loadJson(fileChild(folderChild(s,'identidade'),'identidade.json'),'identidade');const b=document.createElement('button');b.type='button';b.className='viewer-item'+(s.id===viewerSelectedId?' active':'');const name=document.createElement('strong'),id=document.createElement('small');name.textContent=info?.nomeExibicao||info?.nome||s.name;id.textContent=info?.id||s.name;b.append(name,id);b.onclick=()=>{viewerSelectedId=s.id;renderViewerList();renderViewerPreview()};box.append(b)}
 if(!shown.length)box.textContent='Nenhuma tela encontrada.';}
function buildViewerHtml(data){const serialized=JSON.stringify(data).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');
 const css='html,body{margin:0;min-height:100%;font-family:Arial,sans-serif}*{box-sizing:border-box}body{overflow-x:hidden;background:#eef2f6}#app-root{position:relative;min-height:100dvh}#warnings{position:fixed;top:6px;right:6px;max-width:65%;background:#ffefcb;color:#7f4d08;border-radius:7px;padding:5px 7px;z-index:9999;font:10px Arial}#navigation-tip{position:fixed;bottom:10px;left:50%;transform:translateX(-50%);background:#10233f;color:#fff;border-radius:9px;padding:10px;max-width:95%;font:12px Arial;z-index:999999;box-shadow:0 8px 24px #0004}';
 const run=VIEW_RUNTIME_SOURCE;
 return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data: blob:; style-src \'unsafe-inline\'; script-src \'unsafe-inline\'; font-src data:;"><style>'+css+'</style></head><body><div id="app-root"></div><div id="warnings" hidden></div><div id="navigation-tip" hidden></div><script type="application/json" id="view-data">'+serialized+'<\/script><script>'+run+'<\/script></body></html>';
}
function renderViewerPreview(){let s=getViewerScreen();if(!s){E('viewerName').textContent='Nenhuma tela selecionada';E('viewerFrame').srcdoc='';return}
 try{const d=normalizeScreen(s);E('viewerName').textContent=d.identidade.nomeExibicao||d.identidade.nome||s.name;E('viewerId').textContent=d.id;
 const slots=Object.keys(d.instancias).length;const defs=Object.keys(d.definicoes).length;const tags=[String(d.identidade.namespace||''),String(d.classificacao.escopo||''),slots+' instâncias',defs+' componentes'];
 E('viewerMeta').replaceChildren();for(const t of tags){if(!t)continue;const chip=document.createElement('span');chip.className='viewer-chip';chip.textContent=t;E('viewerMeta').append(chip)}
 viewerHtml=buildViewerHtml(d);E('viewerFrame').srcdoc=viewerHtml;E('viewerFeedback').textContent='Prévia estática montada exclusivamente de identidade, estrutura e componentes. Menus abrem/fecham localmente; destinos são informativos. Navegação real, estados, ações, dados e mocks não são executados.';
 }catch(e){E('viewerName').textContent=s.name;E('viewerId').textContent='';E('viewerFeedback').textContent='Não foi possível montar esta tela: '+e.message;E('viewerFrame').srcdoc='<p style="padding:25px;font-family:Arial">Erro no contrato: '+String(e.message).replace(/[&<>]/g,'')+'</p>';viewerHtml='';}}
function openScreenInViewer(s){if(!s)return toast('Selecione uma tela para visualizar.',true);viewerSelectedId=s.id;switchTab('visualizador');renderViewerPreview()}
function chooseViewerLayout(layout){viewerLayout=layout;E('viewerDevice').classList.toggle('desktop',layout==='desktop');E('viewerPhone').classList.toggle('active',layout==='phone');E('viewerDesktop').classList.toggle('active',layout==='desktop');}

